import React from 'react';
import { ShieldCheck } from 'lucide-react';

const SecurityCard = () => {
  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl p-6 shadow-lg border border-white/30 dark:border-neutral-800/50">
      <div className="flex items-center space-x-3 mb-4">
        <div className="h-12 w-12 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
          <ShieldCheck className="h-6 w-6 text-white" />
        </div>
        <div>
          <h3 className="font-bold text-neutral-900 dark:text-white">Sécurité</h3>
          <p className="text-sm text-neutral-600 dark:text-neutral-400">Statut: Excellent</p>
        </div>
      </div>
      <button className="w-full py-2.5 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white/50 dark:bg-neutral-800/50 text-neutral-700 dark:text-neutral-300 hover:border-primary-500 hover:text-primary-600 dark:hover:text-primary-400 transition-colors">
        Changer le mot de passe
      </button>
    </div>
  );
};

export default SecurityCard;
